PREFIX energia: <https://w3id.org/rastro/energia#>

SELECT ?concesion
WHERE {
  {
    SELECT ?c (COUNT(?venteo) AS ?cantidad_venteos)
    WHERE {
      ?venteo a energia:DetectedVenting ;
              energia:inConcession ?c .
    }
    GROUP BY ?c
    ORDER BY DESC(?cantidad_venteos)
    LIMIT 5
  }
  ?c energia:name ?concesion .
}
ORDER BY DESC(?cantidad_venteos)
LIMIT 50

PREFIX energia: <https://w3id.org/rastro/energia#>

SELECT (COUNT(?venteo) AS ?cantidad_venteos)
WHERE {
  ?concesion energia:name "LOMA CAMPANA" .
  ?venteo a energia:DetectedVenting ;
          energia:inConcession ?concesion .
}
LIMIT 50

PREFIX energia: <https://w3id.org/rastro/energia#>

SELECT (COUNT(DISTINCT ?pozo) AS ?pozos)
WHERE {
  ?pozo a energia:Well ;
        energia:operator ?empresa .
  ?empresa energia:name ?empresa_nombre .
  FILTER(REGEX(STR(?empresa_nombre), "^YPF(\\b|\\s|\\.)", "i"))
}
LIMIT 50

PREFIX energia: <https://w3id.org/rastro/energia#>

