PREFIX energia: <https://w3id.org/rastro/energia#>

SELECT (COUNT(DISTINCT ?concesion) AS ?concesiones_para_revisar)
WHERE {
  ?concesion a energia:ConcessionToReview .
}
LIMIT 50

PREFIX energia: <https://w3id.org/rastro/energia#>

SELECT (COUNT(DISTINCT ?concesion) AS ?concesiones_con_dos_motivos)
WHERE {
  ?concesion a energia:VentingFarFromPipeline ;
             a energia:VentingWithoutReports .
}
LIMIT 50

PREFIX energia: <https://w3id.org/rastro/energia#>

SELECT (SUM(?petroleo) AS ?petroleo_m3)
WHERE {
  {
    SELECT DISTINCT ?empresa
    WHERE {
      {
        ?empresa energia:name ?nombre_empresa .
      }
      UNION
      {
        ?nombre a energia:CompanyName ;
          energia:company ?empresa ;
          energia:nameInSource ?nombre_empresa .
      }
      FILTER(REGEX(STR(?nombre_empresa), "^YPF(\\b|\\s|\\.)", "i"))
    }
  }
  ?produccion a energia:WellProduction ;
    energia:declaredBy ?empresa ;
    energia:oil ?petroleo .
}
LIMIT 50
